{
  "title": "Discussion on tax filing, domain buying, app profitability and security concerns",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing and related costs",
      "claims": [
        {
          "text": "The user paid about 500 UAH to aunt Sveta to avoid large penalties from incorrectly marked columns in declarations.",
          "evidence": [1]
        },
        {
          "text": "The inspector approved the declarations without reviewing them for 1.5 years and was later reprimanded.",
          "evidence": [1]
        },
        {
          "text": "With Sveta's help the user re‑filed correctly and paid roughly 1000 UAH instead of all fines.",
          "evidence": [1]
        },
        {
          "text": "The tax calculation process takes about an hour with Excel, sometimes a day per month.",
          "evidence": [5,6]
        },
        {
          "text": "Quarterly reports must be filed and taxes paid on time.",
          "evidence": [7]
        },
        {
          "text": "Mistakes often come from not checking which column to subtract which number.",
          "evidence": [8]
        },
        {
          "text": "A calculator only works with a UAH‑registered FOP; the user had to convert all transactions at the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase considerations",
      "claims": [
        {
          "text": "User P2 has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "User P4 opposes buying a domain, calling it a worthless thing.",
          "evidence": [9,10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a small app project",
      "claims": [
        {
          "text": "Web platforms are the simplest but less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "Web SEO is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "No external traffic sources (Instagram, X, Threads) or contextual ads are available.",
          "evidence": [11]
        },
        {
          "text": "User acquisition is almost zero because a paywall appears within the first 10 seconds.",
          "evidence": [11]
        },
        {
          "text": "Conversion is presumed zero; the product does not simplify anything or integrate with banks or tax cabinets.",
          "evidence": [11]
        },
        {
          "text": "Successful cases use fast delivery (<1 week) and cross‑platform stacks like Flutter, copying popular ideas with minor tweaks.",
          "evidence": [12]
        },
        {
          "text": "The discussed project likely targets LinkedIn audience, which now has fewer technical/managerial posts (<50%).",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "security-concerns",
      "title": "Security and source code questions",
      "claims": [
        {
          "text": "User P1 asks if the source code can be found by searching for the password.",
          "evidence": [21]
        },
        {
          "text": "User P4 jokes they did not pay 299 UAH for it and hints the password is stored in local storage as a 100% discount promo code.",
          "evidence": [22,23,24,26,28,29,30,32]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Can the source code be retrieved by searching for the password?",
      "evidence": [21]
    }
  ]
